params.command:
$ErrorActionPreference='Stop'
$root = Join-Path $env:TEMP 'mhw-updater-e2e-harness-build-a2'
if (Test-Path $root) { Remove-Item -Recurse -Force $root }
git clone --no-tags --branch agent/updater-installed-client-e2e-harness-20260929 https://github.com/fengie/mhw-mods.git $root
if ($LASTEXITCODE -ne 0) { throw 'clone failed' }
$proj = Join-Path $root 'tests\MhwModManager.IntegrationTests\MhwModManager.IntegrationTests.csproj'
dotnet restore $proj --source (Join-Path $root 'data') -p:NuGetAudit=false --ignore-failed-sources
if ($LASTEXITCODE -ne 0) { throw 'restore failed' }
dotnet build $proj -c Release --no-restore -p:NuGetAudit=false
if ($LASTEXITCODE -ne 0) { throw 'build failed' }
git -C $root status --short
git -C $root rev-parse HEAD
